    22|export type IVXChatExecutionStatus = {
    23|  taskId: string;
    24|  status: string;
    25|  stage: string;
    26|  liveProgress: number;
    27|  filesChanged: string[];
    28|  tests: { run: boolean; passed: boolean; command: string | null };
    29|  commitSha: string | null;
    30|  deploymentId: string | null;
    31|  evidence: {
    32|    deployedToProduction: boolean;
    33|    liveCommit: string | null;
    34|    commitMatch: boolean;
    35|    healthOk: boolean;
    36|    typecheck: { run: boolean; passed: boolean };
    37|    buildRun: boolean;
    38|    finalStatus: string;
    39|    error: string | null;
    40|    answerBlock: string;
    41|  } | null;
    42|  httpStatus: 200 | 202;
    43|  category: string | null;
