    48|const TERMINAL_STATUSES = new Set(['completed', 'failed', 'blocked', 'cancelled']);
    49|
    50|function isRecord(value: unknown): value is Record<string, unknown> {
    51|  return typeof value === 'object' && value !== null && !Array.isArray(value);
    52|}
    53|
    54|function coerceStatus(payload: unknown): IVXChatExecutionStatus | null {
    55|  if (!isRecord(payload)) return null;
    56|  const taskId = typeof payload.taskId === 'string' ? payload.taskId : null;
    57|  const statusUrl = typeof payload.statusUrl === 'string' ? payload.statusUrl : null;
    58|  if (!taskId || !statusUrl) return null;
    59|  const testsRaw = isRecord(payload.tests) ? payload.tests : {};
    60|  const evidenceRaw = isRecord(payload.evidence) ? payload.evidence : null;
    61|  const typecheckField = evidenceRaw?.typecheck;
    62|  const typecheckRaw = isRecord(typecheckField) ? typecheckField : {};
    63|  return {
    64|    taskId,
    65|    status: typeof payload.status === 'string' ? payload.status : 'unknown',
    66|    stage: typeof payload.stage === 'string' ? payload.stage : 'UNKNOWN',
    67|    liveProgress: typeof payload.liveProgress === 'number' ? payload.liveProgress : 0,
    68|    filesChanged: Array.isArray(payload.filesChanged)
    69|      ? payload.filesChanged.filter((f): f is string => typeof f === 'string')
    70|      : [],
    71|    tests: {
    72|      run: typeof testsRaw.run === 'boolean' ? testsRaw.run : false,
    73|      passed: typeof testsRaw.passed === 'boolean' ? testsRaw.passed : false,
    74|      command: typeof testsRaw.command === 'string' ? testsRaw.command : null,
    75|    },
    76|    commitSha: typeof payload.commitSha === 'string' ? payload.commitSha : null,
    77|    deploymentId: typeof payload.deploymentId === 'string' ? payload.deploymentId : null,
    78|    evidence: evidenceRaw
    79|      ? {
    80|          deployedToProduction: typeof evidenceRaw.deployedToProduction === 'boolean' ? evidenceRaw.deployedToProduction : false,
    81|          liveCommit: typeof evidenceRaw.liveCommit === 'string' ? evidenceRaw.liveCommit : null,
    82|          commitMatch: typeof evidenceRaw.commitMatch === 'boolean' ? evidenceRaw.commitMatch : false,
    83|          healthOk: typeof evidenceRaw.healthOk === 'boolean' ? evidenceRaw.healthOk : false,
    84|          typecheck: {
    85|            run: typeof typecheckRaw.run === 'boolean' ? typecheckRaw.run : false,
    86|            passed: typeof typecheckRaw.passed === 'boolean' ? typecheckRaw.passed : false,
    87|          },
    88|          buildRun: typeof evidenceRaw.buildRun === 'boolean' ? evidenceRaw.buildRun : false,
    89|          finalStatus: typeof evidenceRaw.finalStatus === 'string' ? evidenceRaw.finalStatus : 'UNKNOWN',
    90|          error: typeof evidenceRaw.error === 'string' ? evidenceRaw.error : null,
    91|          answerBlock: typeof evidenceRaw.answerBlock === 'string' ? evidenceRaw.answerBlock : '',
    92|        }
    93|      : null,
