   101|type PollState = {
   102|  status: IVXChatExecutionStatus | null;
   103|  polling: boolean;
   104|  error: string | null;
   105|  attempts: number;
   106|};
   107|
   108|const DEFAULT_POLL_INTERVAL_MS = 2500;
   109|const MAX_POLL_ATTEMPTS = 80; // ~3.3min at 2.5s — ample for senior-dev tasks
   110|
   111|/**
   112| * Poll the worker statusUrl for live execution updates until the job reaches
   113| * a terminal state (completed/failed/blocked/cancelled) or the attempt cap
   114| * fires. Returns the latest status plus the terminal answerBlock so the chat
   115| * can swap the live-progress bubble for the final verified-evidence block.
   116| */
   117|export function useExecutionStatusPoll(
   118|  initialStatus: IVXChatExecutionStatus | null,
   119|  authToken: string | null,
   120|  options: { pollIntervalMs?: number; maxAttempts?: number } = {},
   121|): PollState & {
   122|  refresh: () => void;
   123|  stop: () => void;
   124|} {
   125|  const pollIntervalMs = options.pollIntervalMs ?? DEFAULT_POLL_INTERVAL_MS;
   126|  const maxAttempts = options.maxAttempts ?? MAX_POLL_ATTEMPTS;
   127|  const [state, setState] = useState<PollState>({
   128|    status: initialStatus,
   129|    polling: initialStatus !== null && !TERMINAL_STATUSES.has(initialStatus?.status ?? ''),
   130|    error: null,
   131|    attempts: 0,
   132|  });
   133|  const stoppedRef = useRef(false);
   134|  const authTokenRef = useRef(authToken);
   135|  authTokenRef.current = authToken;
   136|
   137|  const isTerminal = useCallback((s: IVXChatExecutionStatus | null): boolean => {
   138|    return s !== null && TERMINAL_STATUSES.has(s.status);
   139|  }, []);
   140|
   141|  const pollOnce = useCallback(async (): Promise<void> => {
   142|    const current = stateRef.current.status;
   143|    if (!current || stoppedRef.current || isTerminal(current)) {
   144|      setState((prev) => ({ ...prev, polling: false }));
   145|      return;
   146|    }
   147|    const url = current.statusUrl.startsWith('http')
   148|      ? current.statusUrl
   149|      : `${BASE_URL}${current.statusUrl}`;
   150|    try {
   151|      const response = await fetch(url, {
   152|        method: 'GET',
   153|        headers: {
   154|          'Content-Type': 'application/json',
   155|          ...(authTokenRef.current ? { Authorization: `Bearer ${authTokenRef.current}` } : {}),
   156|        },
   157|      });
   158|      if (!response.ok) {
   159|        // 404/401 → keep the last status but stop polling to avoid a loop.
   160|        setState((prev) => ({
   161|          ...prev,
   162|          polling: false,
   163|          error: `status endpoint returned ${response.status}`,
   164|          attempts: prev.attempts + 1,
   165|        }));
   166|        stoppedRef.current = true;
   167|        return;
   168|      }
   169|      const body = await response.json().catch(() => null);
   170|      const job = isRecord(body) && isRecord(body.job) ? body.job : isRecord(body) ? body : null;
   171|      const next = coerceStatus(job);
   172|      if (!next) {
   173|        setState((prev) => ({ ...prev, attempts: prev.attempts + 1 }));
   174|        return;
   175|      }
   176|      setState((prev) => ({
   177|        status: next,
   178|        polling: !TERMINAL_STATUSES.has(next.status),
   179|        error: null,
   180|        attempts: prev.attempts + 1,
   181|      }));
   182|      if (TERMINAL_STATUSES.has(next.status)) {
   183|        stoppedRef.current = true;
   184|      }
   185|    } catch (error) {
   186|      setState((prev) => ({
   187|        ...prev,
   188|        error: error instanceof Error ? error.message : 'poll failed',
   189|        attempts: prev.attempts + 1,
   190|      }));
   191|    }
   192|  }, [isTerminal]);
   193|
   194|  // Keep a ref of the latest state so the interval callback reads fresh data.
   195|  const stateRef = useRef(state);
   196|  stateRef.current = state;
   197|
   198|  useEffect(() => {
   199|    if (!initialStatus || isTerminal(initialStatus)) {
   200|      return;
   201|    }
   202|    stoppedRef.current = false;
   203|    const intervalId = setInterval(() => {
   204|      void pollOnce();
   205|    }, pollIntervalMs);
   206|    // Fire one immediate poll so the bubble advances past "queued" quickly.
   207|    void pollOnce();
   208|    return () => {
   209|      clearInterval(intervalId);
   210|      stoppedRef.current = true;
   211|    };
   212|    // eslint-disable-next-line react-hooks/exhaustive-deps
   213|  }, [initialStatus?.taskId, pollIntervalMs]);
   214|
   215|  // Hard stop after maxAttempts to prevent unbounded polling.
   216|  useEffect(() => {
   217|    if (state.attempts >= maxAttempts && state.polling) {
   218|      setState((prev) => ({ ...prev, polling: false, error: prev.error ?? 'poll timeout' }));
   219|      stoppedRef.current = true;
   220|    }
   221|  }, [state.attempts, state.polling, maxAttempts]);
   222|
   223|  const refresh = useCallback(() => {
   224|    stoppedRef.current = false;
   225|    setState((prev) => ({ ...prev, polling: true, error: null }));
   226|    void pollOnce();
   227|  }, [pollOnce]);
   228|
   229|  const stop = useCallback(() => {
   230|    stoppedRef.current = true;
   231|    setState((prev) => ({ ...prev, polling: false }));
   232|  }, []);
   233|
   234|  return { ...state, refresh, stop };
   235|}
